const categories = CATEGORY_DATA.map((c, ci) => ({...c, id:`cat-${ci}`, words:c.items.split(',').map((item, wi) => {
  const [word, meaning, emoji] = item.split('|');
  const cleanWord = word.trim();
  return {id:`${ci}-${cleanWord}`, word:cleanWord, meaning:meaning.trim(), emoji:emoji.trim(), category:c.name, categoryId:`cat-${ci}`, example:exampleFor(c.name, cleanWord), sentenceMeaning:sentenceMeaningFor(c.name, cleanWord, meaning.trim()), index:wi};
})}));
const allWords = categories.flatMap(c => c.words);
const wordById = new Map(allWords.map(w => [w.id,w]));
const wordByName = new Map();
allWords.forEach(w => {if(!wordByName.has(w.word)) wordByName.set(w.word,w)});
function exampleFor(category, word){
  const templates={
    'Everyday Objects':`I use my ${word} every day.`,
    'Food and Drinks':`I like ${word}.`,
    'Animals':`The ${word} is an animal.`,
    'Family and Friends':`My ${word} is kind.`,
    'School':`I learn about this at school: ${word}.`,
    'Colors and Shapes':({red:'The apple is red.',blue:'The sky is blue.',yellow:'The sun is yellow.',green:'The leaf is green.',purple:'The flower is purple.',orange:'The orange is orange.',pink:'The flower is pink.',black:'My bag is black.',white:'The cloud is white.',brown:'The bear is brown.',circle:'A wheel is a circle.',square:'The window looks like a square.',triangle:'The sign is a triangle.',star:'I see a star.',heart:'I draw a heart.',diamond:'The diamond shines.',oval:'The egg is oval.'})[word]||`I can see a ${word}.`,
    'Numbers':`I can count to ${word}.`,
    'Body Parts':`My ${word} is part of my body.`,
    'Actions and Verbs':`I can ${word}.`,
    'Emotions':`I feel ${word} today.`,
    'Places':`I go to the ${word}.`,
    'Nature':({sun:'The sun is bright.',moon:'The moon shines at night.',star:'I can see a star.',cloud:'A cloud is in the sky.',rain:'The rain makes the garden fresh.',wind:'The wind is cool.',tree:'The tree is tall.',flower:'The flower is beautiful.',grass:'The grass is green.',river:'The river flows to the sea.',mountain:'The mountain is very high.',ocean:'The ocean is blue.',forest:'Many animals live in the forest.',leaf:'A leaf falls from the tree.',stone:'The stone is small.',sky:'The sky looks beautiful.',rainbow:'A rainbow has many colors.'})[word]||`I love nature.`
  };
  return templates[category]||`I am learning the word ${word}.`;
}
function sentenceMeaningFor(category, word, meaning){
  const templates={
    'Everyday Objects':`Aku menggunakan ${meaning} setiap hari.`, 'Food and Drinks':`Aku suka ${meaning}.`, 'Animals':`Itu adalah ${meaning}.`,
    'Family and Friends':`${meaning} saya baik hati.`, 'School':`Aku belajar tentang ${meaning} di sekolah.`, 'Colors and Shapes':`Aku bisa melihat bentuk atau warna ${meaning}.`,
    'Numbers':`Aku bisa menghitung sampai ${meaning}.`, 'Body Parts':`${meaning} adalah bagian dari tubuhku.`, 'Actions and Verbs':`Aku bisa ${meaning}.`,
    'Emotions':`Aku merasa ${meaning} hari ini.`, 'Places':`Aku pergi ke ${meaning}.`, 'Nature':`Aku melihat ${meaning} di alam.`
  };
  return templates[category]||`Aku sedang belajar kata ${meaning}.`;
}
const STORAGE_KEY='wordmasterAcademy_v1';
const localDateKey=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const todayKey=()=>localDateKey();
const yesterdayKey=()=>{const d=new Date();d.setDate(d.getDate()-1);return localDateKey(d)};
const emptyDaily=()=>({date:todayKey(),words:0,learnedWords:[],games:0,flashcards:0,flashcardWords:[],quests:{}});
function defaultState(){return {name:'Word Explorer',xp:0,coins:0,streak:0,lastActiveDate:'',activeDates:[],listenMode:'en-en',learned:[],review:[],mastered:[],totalQuestions:0,correctAnswers:0,gamesCompleted:0,flashcardsViewed:0,categoryVisits:{},sound:true,daily:emptyDaily(),badges:[],lastWordId:allWords[0]?.id||'',view:'home'};}
function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return defaultState();const val={...defaultState(),...JSON.parse(raw)};if(!val.daily||val.daily.date!==todayKey())val.daily=emptyDaily();if(!val.daily.quests)val.daily.quests={};if(!Array.isArray(val.daily.learnedWords))val.daily.learnedWords=[];if(!Array.isArray(val.daily.flashcardWords))val.daily.flashcardWords=[];if(!Array.isArray(val.learned))val.learned=[];if(!Array.isArray(val.review))val.review=[];if(!Array.isArray(val.mastered))val.mastered=[];if(!Array.isArray(val.activeDates))val.activeDates=[];if(!['en-en','id-en'].includes(val.listenMode))val.listenMode='en-en';return val;}catch(e){return defaultState();}}
let state=loadState();
let currentView='home';
let selectedCategory='all';
let flashDeck=[];let flashIndex=0;let flashFlipped=false;let flashSeen=new Set();
let listenSession=null;let scrambleSession=null;let matchSession=null;
let quizDeck=[];
const el=id=>document.getElementById(id);
const workspace=el('workspace');
function saveState(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){toast('Progress could not be saved in this browser.','⚠️');}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function shuffle(array){const a=[...array];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function pickRandom(except=[], pool=allWords){const excluded=new Set(except);const possible=pool.filter(w=>!excluded.has(w.id));return possible[Math.floor(Math.random()*possible.length)]||pool[0];}
function getLevel(){const lvl=Math.floor(state.xp/100)+1;const names=['Word Explorer','Word Adventurer','Vocabulary Hero','Word Wizard','Language Champion','Word Legend'];return {number:lvl,name:names[Math.min(names.length-1,lvl-1)]||'Word Legend',progress:state.xp%100};}
function startActiveDay(){const today=todayKey();if(!Array.isArray(state.activeDates))state.activeDates=[];if(state.lastActiveDate===today){if(!state.activeDates.includes(today))state.activeDates.push(today);return 'already-counted';}const continued=state.lastActiveDate===yesterdayKey();state.streak=continued?Math.max(0,Number(state.streak)||0)+1:1;state.lastActiveDate=today;state.activeDates=[...new Set([...state.activeDates,today])].slice(-120);return continued?'continued':state.activeDates.length===1?'first-login':'restarted';}
function updateStatsUI(){const level=getLevel();el('headerStreak').textContent=state.streak;const headerFlame=el('headerFlame');if(headerFlame)headerFlame.innerHTML=renderFlameGuardian('mini');const dockFlame=el('dockFlame');if(dockFlame)dockFlame.innerHTML=renderFlameGuardian('dock');el('headerCoins').textContent=state.coins;el('xpValue').textContent=state.xp;el('wordsLearnedValue').textContent=state.learned.length;el('accuracyValue').textContent=state.totalQuestions?`${Math.round(state.correctAnswers/state.totalQuestions*100)}%`:'—';el('levelLabel').textContent=level.name;el('heroLevel').textContent=`LV ${level.number}`;el('heroProgressFill').style.width=`${Math.max(5,level.progress)}%`;el('missionSummary').textContent=state.daily.words>=5?'Mission complete! Amazing work!':`Learn ${5-state.daily.words} more word${5-state.daily.words===1?'':'s'} and earn a star!`;renderQuestList();renderBadges();}
function checkQuests(){const d=state.daily;const definitions=[['words',5,'words','Learn 5 words'],['games',1,'games','Play one mini-game'],['flashcards',10,'flashcards','Review 10 flashcards']];definitions.forEach(([key,target,field,label])=>{if((d[key]||0)>=target&&!d.quests[key]){d.quests[key]=true;state.coins+=15;state.xp+=5;toast(`${label} complete! +15 coins`,'🌟');confettiBurst();}});}
function renderQuestList(){const d=state.daily;const entries=[{key:'words',target:5,value:d.words||0,title:'Learn 5 new words',reward:'+15 🪙',icon:'📚'},{key:'games',target:1,value:d.games||0,title:'Play one mini-game',reward:'+15 🪙',icon:'🎮'},{key:'flashcards',target:10,value:d.flashcards||0,title:'Review 10 flashcards',reward:'+15 🪙',icon:'🃏'}];const done=entries.filter(q=>d.quests[q.key]||(q.value>=q.target)).length;el('questCount').textContent=`${done}/3`;el('questList').innerHTML=entries.map(q=>{const isDone=!!d.quests[q.key]||q.value>=q.target;return `<div class="quest-item ${isDone?'done':''}"><span class="quest-check">${isDone?'✓':q.icon}</span><div class="quest-detail"><strong>${q.title}</strong><small>${Math.min(q.value,q.target)}/${q.target} completed</small></div><span class="quest-reward">${isDone?'DONE':q.reward}</span></div>`}).join('');}
function badgeDefs(){return [{id:'first-five',icon:'⭐',title:'First 5 words',earned:state.learned.length>=5},{id:'word-collector',icon:'📚',title:'25 words learned',earned:state.learned.length>=25},{id:'listener',icon:'🎧',title:'5 games completed',earned:state.gamesCompleted>=5},{id:'streak-seven',icon:'🔥',title:'7-day streak',earned:state.streak>=7},{id:'century',icon:'💯',title:'100 words learned',earned:state.learned.length>=100},{id:'flash-pro',icon:'🃏',title:'10 flashcards today',earned:state.daily.flashcards>=10}];}
function renderBadges(){const badges=badgeDefs();const earned=badges.filter(b=>b.earned);el('badgeRow').innerHTML=badges.slice(0,4).map(b=>`<div class="badge-medal ${b.earned?'':'locked'}" title="${escapeHtml(b.title)}">${b.icon}</div>`).join('');el('badgeCaption').textContent=earned.length?`You've unlocked ${earned.length} badge${earned.length>1?'s':''}. Keep going!`:'Play games to collect your first badges.';const newly=badges.filter(b=>b.earned&&!state.badges.includes(b.id));if(newly.length){newly.forEach(b=>{state.badges.push(b.id);toast(`Badge unlocked: ${b.title}!`,b.icon)});saveState();}}
function award({xp=0,coins=0,word=null,question=false,correct=false,flashcard=false}={}){
  state.xp+=xp;state.coins+=coins;
  if(question){state.totalQuestions++;if(correct)state.correctAnswers++;}
  if(word&&correct){if(!state.learned.includes(word.id)){state.learned.push(word.id);state.daily.learnedWords=state.daily.learnedWords||[];if(!state.daily.learnedWords.includes(word.id)){state.daily.learnedWords.push(word.id);state.daily.words=state.daily.learnedWords.length;}}state.lastWordId=word.id;}
  if(flashcard&&word){state.daily.flashcardWords=state.daily.flashcardWords||[];if(!state.daily.flashcardWords.includes(word.id)){state.daily.flashcardWords.push(word.id);state.daily.flashcards=state.daily.flashcardWords.length;state.flashcardsViewed++;}}
  if(xp>0||coins>0||word||flashcard){startActiveDay();checkQuests();saveState();updateStatsUI();}
}
function recordGameFinished(){state.gamesCompleted++;state.daily.games=(state.daily.games||0)+1;startActiveDay();checkQuests();saveState();updateStatsUI();}
function toast(message,icon='✨'){const node=document.createElement('div');node.className='toast';node.innerHTML=`<span class="toast-icon">${icon}</span><span>${escapeHtml(message)}</span>`;el('toastStack').appendChild(node);setTimeout(()=>{node.style.opacity='0';node.style.transform='translateY(8px)';setTimeout(()=>node.remove(),250)},3000);}
function confettiBurst(){const colors=['✦','✧','★','●','◆','✿'];for(let i=0;i<22;i++){const p=document.createElement('span');p.className='confetti';p.textContent=colors[i%colors.length];p.style.left=`${4+Math.random()*92}vw`;p.style.top=`${5+Math.random()*13}vh`;p.style.color=['#ffcb4e','#52c8a7','#ff8276','#9261c8','#53b6d1'][i%5];p.style.setProperty('--drift',`${(Math.random()-.5)*220}px`);p.style.animationDelay=`${Math.random()*.3}s`;document.body.appendChild(p);setTimeout(()=>p.remove(),1700);}}
function speak(text,language='en-US'){if(!state.sound)return;if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){toast('Audio pronunciation is not supported in this browser.','🔇');return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text));u.lang=language;u.rate=language.toLowerCase().startsWith('id')?.9:.82;u.pitch=1.04;const voices=window.speechSynthesis.getVoices();const prefix=language.split('-')[0].toLowerCase();const exact=voices.find(v=>v.lang.toLowerCase()===language.toLowerCase());const voice=exact||voices.find(v=>v.lang.toLowerCase().startsWith(prefix+'-'))||voices.find(v=>v.lang.toLowerCase().startsWith(prefix+'_'))||voices.find(v=>v.lang.toLowerCase().startsWith(prefix));if(voice)u.voice=voice;window.speechSynthesis.speak(u);}
function setCharacterMessage(message){el('characterMessage').textContent=message;}
function setView(view,scroll=true){currentView=view;state.view=view;saveState();document.querySelectorAll('[data-view]').forEach(btn=>btn.classList.toggle('active',btn.dataset.view===view));if(view==='home'){el('sectionTitle').textContent='What shall we learn today?';renderHome();}else if(view==='vocabulary'){el('sectionTitle').textContent='Explore new words';renderVocabulary();}else if(view==='games'){el('sectionTitle').textContent='Choose a mini-game';renderGames();}else if(view==='progress'){el('sectionTitle').textContent='Look how far you’ve come!';renderProgress();}else if(view==='streak'){el('sectionTitle').textContent='Your flame grows with every daily login';renderStreak();}if(scroll&&window.innerWidth<740)el('appSection').scrollIntoView({behavior:'smooth',block:'start'});}
function renderHome(){const cats=categories.map(c=>`<button class="category-card" style="--tile:${c.color};--tile-color:${c.accent}" data-action="open-category" data-category="${c.id}"><span class="cat-emoji">${c.icon}</span><strong>${escapeHtml(c.name)}</strong><small>${c.words.length} words · ${c.words.filter(w=>state.learned.includes(w.id)).length} learned</small>${c.words.every(w=>state.learned.includes(w.id))?'<span class="cat-check">✓</span>':''}</button>`).join('');workspace.innerHTML=`<div class="panel-head"><div><h3>Explore your word worlds 🌍</h3><p>Pick a world and discover new words one game at a time.</p></div><button class="inline-link" data-action="all-vocabulary">All words →</button></div><div class="category-grid">${cats}</div><div class="panel-head" style="margin-top:25px"><div><h3>Choose your listening mode 🎧</h3><p>Both listening games use English words as answers.</p></div><button class="inline-link" data-action="streak-home">🔥 Streak ${state.streak} →</button></div><div class="game-launch-grid listening-mode-grid">${listenModeCard('listen-english','🇬🇧','English Audio → English Answers','Hear an English word, then choose the matching English word.','#e3faf2','en-en')}${listenModeCard('listen-indonesian','🇮🇩','Indonesian Audio → English Answers','Hear the Indonesian meaning, then choose the English word.','#f2e8ff','id-en')}</div><div class="panel-head" style="margin-top:25px"><div><h3>More mini-games 🎮</h3><p>Little games with big vocabulary power.</p></div></div><div class="game-launch-grid">${gameCard('flashcards','🃏','Word Flashcards','Flip, learn, and remember new words.','#f2e8ff')}${gameCard('scramble','🔤','Word Scramble','Put mixed-up letters in the right order.','#fff1db')}${gameCard('matching','🧩','Picture Match','Match pictures to English words.','#ffe9ed')}</div>`;}
function gameCard(action,icon,title,description,color){return `<button class="game-card" data-action="${action}" style="--tile:${color}"><span class="game-card-icon">${icon}</span><span class="game-card-copy"><strong>${title}</strong><small>${description}</small></span><span class="game-card-arrow">›</span></button>`;}
function listenModeCard(action,icon,title,description,color,mode){return `<button class="game-card listen-mode-card ${state.listenMode===mode?'mode-selected':''}" data-action="${action}" style="--tile:${color}"><span class="game-card-icon">${icon}</span><span class="game-card-copy"><strong>${title}</strong><small>${description}</small></span><span class="game-card-arrow">›</span></button>`;}
function renderVocabulary(filterText='',categoryId=selectedCategory){selectedCategory=categoryId;const list=categoryId==='all'?allWords:categories.find(c=>c.id===categoryId)?.words||allWords;const text=filterText.trim().toLowerCase();const filtered=list.filter(w=>!text||`${w.word} ${w.meaning} ${w.category}`.toLowerCase().includes(text));workspace.innerHTML=`<div class="panel-head"><div><h3>Meet the words 🧠</h3><p>Tap the speaker to hear the word. Tap a word to see its example.</p></div><span class="game-count">${filtered.length} words</span></div><div class="search-row"><label class="search-box"><span>⌕</span><input id="vocabSearch" type="search" placeholder="Search English or Indonesian..." value="${escapeHtml(filterText)}" autocomplete="off" /></label><select class="select-control" id="categoryFilter" aria-label="Filter by category"><option value="all" ${categoryId==='all'?'selected':''}>All categories</option>${categories.map(c=>`<option value="${c.id}" ${categoryId===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="word-list" id="wordList">${renderWordRows(filtered)}</div>`;}
function renderWordRows(words){if(!words.length)return '<div class="empty-state"><span>🔎</span>No words found. Try another search.</div>';return words.map(w=>`<div class="word-row"><button class="word-emoji" data-action="show-word" data-id="${w.id}" aria-label="View ${escapeHtml(w.word)}">${w.emoji}</button><button class="word-info" style="border:0;background:transparent;text-align:left;padding:0" data-action="show-word" data-id="${w.id}"><strong>${escapeHtml(w.word)}</strong><small>${escapeHtml(w.meaning)} · ${escapeHtml(w.category)}</small></button><button class="word-play" data-action="speak" data-id="${w.id}" aria-label="Pronounce ${escapeHtml(w.word)}">🔊</button></div>`).join('');}
function renderGames(){workspace.innerHTML=`<div class="panel-head"><div><h3>Choose your listening mode 🎧</h3><p>Both modes keep all answer choices in English.</p></div></div><div class="game-launch-grid listening-mode-grid">${listenModeCard('listen-english','🇬🇧','English Audio → English Answers','Hear an English word, then choose the matching English word.','#e3faf2','en-en')}${listenModeCard('listen-indonesian','🇮🇩','Indonesian Audio → English Answers','Hear the Indonesian meaning, then choose the English word.','#f2e8ff','id-en')}</div><div style="height:18px"></div><div class="panel-head"><div><h3>More mini-games 🚀</h3><p>Practice spelling, memory, and word matching.</p></div></div><div class="game-launch-grid">${gameCard('flashcards','🃏','Word Flashcards','Build memory with flip cards and pronunciation.','#f2e8ff')}${gameCard('scramble','🔤','Word Scramble','Rebuild a word from scrambled letters.','#fff1db')}${gameCard('matching','🧩','Picture Match','Match pictures with their English words.','#ffe9ed')}</div><div style="height:18px"></div><div class="panel-head"><div><h3>Quick practice ✨</h3><p>Practice words you have not mastered yet.</p></div></div><button class="game-card" data-action="review-words" style="width:100%;--tile:#e5f8ef"><span class="game-card-icon">🔁</span><span class="game-card-copy"><strong>Review my tricky words</strong><small>${state.review.length} words marked for review · ${state.learned.length} learned in total</small></span><span class="game-card-arrow">›</span></button>`;}
function renderProgress(){const catRows=categories.map(c=>{const n=c.words.filter(w=>state.learned.includes(w.id)).length;return {name:c.name,icon:c.icon,n,total:c.words.length,pct:Math.round(n/c.words.length*100),color:c.color}}).sort((a,b)=>b.n-a.n);const achievements=badgeDefs();workspace.innerHTML=`<div class="profile-summary"><div class="profile-big-avatar">🧒</div><div style="flex:1;min-width:0"><h3>${escapeHtml(state.name||'Word Explorer')}</h3><p>${getLevel().name} · Level ${getLevel().number} · ${state.streak}-day streak 🔥</p><div class="profile-edit"><input id="nameInput" maxlength="24" value="${escapeHtml(state.name)}" aria-label="Your display name" placeholder="Your name"><button class="mint-button" data-action="save-name">Save</button></div></div></div><div class="panel-head"><div><h3>Your learning journey 📈</h3><p>Every little step counts.</p></div></div><div class="quick-stats" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="quick-stat xp-stat"><span class="quick-stat-icon">⚡</span><div><small>Total XP</small><strong>${state.xp}</strong></div></div><div class="quick-stat word-stat"><span class="quick-stat-icon">📚</span><div><small>Words learned</small><strong>${state.learned.length}</strong></div></div><div class="quick-stat accuracy-stat"><span class="quick-stat-icon">🎯</span><div><small>Quiz accuracy</small><strong>${state.totalQuestions?Math.round(state.correctAnswers/state.totalQuestions*100)+'%':'—'}</strong></div></div><div class="quick-stat"><span class="quick-stat-icon">🎮</span><div><small>Games completed</small><strong>${state.gamesCompleted}</strong></div></div></div><div class="panel-head" style="margin-top:23px"><div><h3>Progress by world 🌍</h3><p>Learn more words to fill each world bar.</p></div></div><div class="progress-list">${catRows.map(c=>`<div class="progress-item"><span class="progress-icon" style="background:${c.color}">${c.icon}</span><div class="progress-info"><div class="progress-label"><span>${escapeHtml(c.name)}</span><small>${c.n}/${c.total} · ${c.pct}%</small></div><div class="bar-track"><span style="width:${c.pct}%"></span></div></div></div>`).join('')}</div><div class="panel-head" style="margin-top:24px"><div><h3>Achievements 🏆</h3><p>${achievements.filter(b=>b.earned).length} of ${achievements.length} collected.</p></div></div><div class="badge-row">${achievements.map(b=>`<div class="badge-medal ${b.earned?'':'locked'}" title="${escapeHtml(b.title)}">${b.icon}</div>`).join('')}</div>`;}
function getStreakStage(days=state.streak){const n=Math.max(0,Number(days)||0);if(n>=100)return {key:'blue',name:'Frostfire Guardian',maturity:'Ancient flame',start:100,next:null,color:'#8bdbf8',message:'Your flame has become a legendary guide.'};if(n>=50)return {key:'purple',name:'Mighty Flame',maturity:'Mature guardian',start:50,next:100,color:'#9a61dd',message:'Your flame is strong, steady, and wise.'};if(n>=25)return {key:'red',name:'Brave Ember',maturity:'Growing guardian',start:25,next:50,color:'#f15b52',message:'Your little flame has grown brave and powerful.'};return {key:'yellow',name:'Little Spark',maturity:'Fire child',start:0,next:25,color:'#ffc93e',message:'A cheerful little flame is starting its journey.'};}
function renderFlameGuardian(size='mini',days=state.streak){const st=getStreakStage(days);let accessory='';if(st.key==='yellow')accessory='<path class="guardian-accessory" d="M51 22 L55 14 L60 21 L68 17 L67 27 L57 30 Z" />';else if(st.key==='red')accessory='<path class="guardian-accessory" d="M35 43 Q60 33 85 43 L83 50 Q60 41 37 50 Z" />';else if(st.key==='purple')accessory='<path class="guardian-accessory" d="M34 37 L35 23 L47 31 L60 14 L73 31 L85 23 L86 39 Z" /><path class="guardian-jewel" d="M56 25 L60 20 L64 25 L60 30 Z" />';else accessory='<path class="guardian-accessory" d="M31 37 L32 19 L45 29 L60 8 L75 29 L88 19 L89 39 Z" /><path class="guardian-jewel" d="M56 21 L60 16 L64 21 L60 26 Z" /><path class="guardian-beard" d="M43 74 Q60 91 77 74 Q76 91 60 96 Q44 91 43 74 Z" />';return `<svg class="flame-guardian stage-${st.key} flame-${size}" viewBox="0 0 120 120" role="img" aria-label="${escapeHtml(st.name)} for a ${days}-day streak"><ellipse class="guardian-shadow" cx="60" cy="104" rx="29" ry="6"/><path class="guardian-outer" d="M59 7 C55 22 42 31 32 44 C18 62 26 90 48 99 C66 107 88 96 94 78 C100 59 86 46 77 36 C72 48 66 51 65 51 C66 34 63 19 59 7Z"/><path class="guardian-inner" d="M61 49 C57 58 47 63 47 75 C47 85 54 91 63 90 C75 89 81 78 75 68 C72 62 66 58 64 52 C63 57 61 60 59 62 C60 56 61 52 61 49Z"/>${accessory}<path class="guardian-brow" d="M42 55 Q49 50 55 55 M66 55 Q73 50 80 55"/><ellipse class="guardian-eye" cx="49" cy="61" rx="3.3" ry="4.4"/><ellipse class="guardian-eye" cx="72" cy="61" rx="3.3" ry="4.4"/><circle class="guardian-eye-glint" cx="50" cy="60" r="1.15"/><circle class="guardian-eye-glint" cx="73" cy="60" r="1.15"/><path class="guardian-smile" d="M51 71 Q60 80 70 71"/><circle class="guardian-cheek" cx="40" cy="69" r="4"/><circle class="guardian-cheek" cx="81" cy="69" r="4"/></svg>`;}
function renderStreak(){const days=Math.max(0,Number(state.streak)||0),stage=getStreakStage(days),next=stage.next,progress=next?Math.max(0,Math.min(100,((days-stage.start)/(next-stage.start))*100)):100,remaining=next?Math.max(0,next-days):0;const milestones=[{days:0,key:'yellow',title:'Little Spark',note:'Yellow · child flame'},{days:25,key:'red',title:'Brave Ember',note:'Red · growing flame'},{days:50,key:'purple',title:'Mighty Flame',note:'Purple · adult flame'},{days:100,key:'blue',title:'Frostfire Guardian',note:'Light blue · legendary flame'}];const today=todayKey();const weekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const lastSeven=Array.from({length:7},(_,i)=>{const date=new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()-(6-i));const key=localDateKey(date);const active=(state.activeDates||[]).includes(key)||state.lastActiveDate===key;return {key,label:weekdays[date.getDay()],day:date.getDate(),active,today:key===today};});workspace.innerHTML=`<div class="streak-page"><section class="streak-hero stage-${stage.key}"><div class="streak-hero-copy"><span class="streak-eyebrow">DAILY LOGIN JOURNEY</span><h3>${days} day${days===1?'':'s'} streak!</h3><p class="streak-stage-name">${stage.name} · ${stage.maturity}</p><p class="streak-stage-message">${stage.message}</p><div class="streak-status-chip">${state.lastActiveDate===today?'✓ Today’s login counted':'Open WordMaster every day to grow your flame'}</div></div><div class="streak-guardian-wrap">${renderFlameGuardian('hero',days)}<span class="guardian-spark spark-left">✦</span><span class="guardian-spark spark-right">✧</span></div></section><section class="streak-progress-card"><div class="streak-progress-heading"><div><strong>${next?`${remaining} more day${remaining===1?'':'s'} to evolve`:'Maximum evolution reached!'}</strong><small>${next?`Next milestone: ${next} days`:'Your flame reached the 100-day form'}</small></div><span class="streak-next-icon">${next||'100+'} 🔥</span></div><div class="streak-progress-track"><span style="width:${progress}%"></span></div><p>${next?`${days} of ${next} days toward your next flame form.`:'Keep your daily streak alive to protect your legend.'}</p></section><section class="streak-week-card"><div class="streak-panel-heading"><div><h3>Last 7 days 📅</h3><p>One login per calendar day counts. Refreshing does not add another day.</p></div><span class="streak-week-badge">🔥 ${days}</span></div><div class="streak-week-grid">${lastSeven.map(d=>`<div class="streak-day ${d.active?'logged':''} ${d.today?'is-today':''}"><span class="streak-day-mark">${d.active?'✓':'·'}</span><strong>${d.label}</strong><small>${d.day}</small></div>`).join('')}</div></section><section class="streak-forms"><div class="streak-panel-heading"><div><h3>Flame evolution 🔥</h3><p>Your companion changes as your daily streak grows.</p></div></div><div class="streak-milestone-grid">${milestones.map(m=>{const st=getStreakStage(m.days);const unlocked=days>=m.days;return `<article class="streak-milestone ${unlocked?'unlocked':'locked'}"><div class="milestone-flame">${renderFlameGuardian('milestone',m.days)}</div><strong>${m.title}</strong><small>${m.days===0?'Starting form':`${m.days}-day milestone`}</small><span class="milestone-description">${m.note}</span><span class="milestone-state">${unlocked?'✓ Unlocked':'🔒 Locked'}</span></article>`;}).join('')}</div></section><div class="streak-actions"><button class="game-primary" data-action="streak-practice">Practice English →</button><button class="outline-button" data-action="streak-go-home">Back to home</button></div></div>`;}
function beginFlashcards(words=null){flashDeck=shuffle((words&&words.length?words:allWords.filter(w=>!state.mastered.includes(w.id))));if(!flashDeck.length)flashDeck=shuffle(allWords);flashDeck=flashDeck.slice(0,Math.min(20,flashDeck.length));flashIndex=0;flashFlipped=false;flashSeen=new Set();renderFlashcard();setViewActive('games');}
function setViewActive(view){currentView=view;document.querySelectorAll('[data-view]').forEach(btn=>btn.classList.toggle('active',btn.dataset.view===view));}
function renderFlashcard(){const w=flashDeck[flashIndex];if(!w){renderGames();return;}workspace.innerHTML=`<div class="panel-head"><div><h3>Word flashcards 🃏</h3><p>Tap the card to turn it over and reveal the meaning.</p></div><button class="inline-link" data-action="games-home">All games</button></div><div class="study-card-wrap"><button class="flashcard ${flashFlipped?'flipped':''}" id="flashCard" aria-label="Flip flashcard"><span class="flash-face front"><span class="flash-emoji">${w.emoji}</span><strong class="flash-word">${escapeHtml(w.word)}</strong><small class="flash-hint">Tap to reveal the meaning</small><span style="margin-top:15px;color:#7fc1ac;font-size:18px">↻</span></span><span class="flash-face back"><strong class="flash-meaning">${escapeHtml(w.meaning)}</strong><small class="flash-hint">${escapeHtml(w.category)}</small><span class="flash-example"><strong>${escapeHtml(w.example)}</strong>${escapeHtml(w.sentenceMeaning)}</span><span style="margin-top:13px;color:#b18b43;font-size:18px">↻</span></span></button><div class="card-counter">CARD ${flashIndex+1} OF ${flashDeck.length}</div><div class="flash-actions"><button class="soft-button" data-action="flash-prev">← Previous</button><button class="soft-button" data-action="speak" data-id="${w.id}">🔊 Listen</button><button class="mint-button" data-action="mark-known" data-id="${w.id}">✓ I know it</button><button class="outline-button" data-action="mark-review" data-id="${w.id}">🔁 Review</button><button class="soft-button" data-action="flash-next">Next →</button></div></div>`;const card=el('flashCard');card.addEventListener('click',()=>{flashFlipped=!flashFlipped;card.classList.toggle('flipped',flashFlipped);if(flashFlipped&&!flashSeen.has(w.id)){flashSeen.add(w.id);award({xp:1,word:null,flashcard:true});}});}
function openListenGame(mode=state.listenMode||'en-en'){state.listenMode=['en-en','id-en'].includes(mode)?mode:'en-en';saveState();listenSession={mode:state.listenMode,questions:shuffle(allWords).slice(0,5),index:0,score:0,answered:false,selected:null,correctCount:0};renderListenQuestion();setCharacterMessage(listenSession.mode==='id-en'?'Listen to the Indonesian meaning!':'Listen to the English word!');setViewActive('games');}
function renderListenQuestion(){if(!listenSession)return;const s=listenSession;if(s.index>=s.questions.length){finishListenGame();return;}const target=s.questions[s.index];const uniqueDistractors=[...new Map(allWords.filter(w=>w.id!==target.id&&w.word!==target.word).map(w=>[w.word,w])).values()];const choices=shuffle([target,...shuffle(uniqueDistractors).slice(0,3)]);s.currentChoices=choices;s.answered=false;s.selected=null;const modeLabel=s.mode==='id-en'?'Indonesian audio · English answers':'English audio · English answers';const promptTitle=s.mode==='id-en'?'Which English word matches?':'What English word do you hear?';const promptHelp=s.mode==='id-en'?'Listen to the Indonesian meaning, then choose the English word.':'Listen to the English word, then choose the same word in English.';workspace.innerHTML=`<div class="panel-head"><div><h3>Listen & Match 🎧</h3><p>${modeLabel}</p></div><button class="inline-link" data-action="games-home">Change mode</button></div><div class="game-board"><div class="game-topline"><span class="game-count">QUESTION ${s.index+1} / ${s.questions.length}</span><span class="game-score">⭐ ${s.score} points</span></div><div class="game-prompt"><button class="listen-target" data-action="listen-target" aria-label="Play ${s.mode==='id-en'?'Indonesian meaning':'English word'}">🔊</button><h4>${promptTitle}</h4><p>${promptHelp}</p></div><div class="choice-grid">${choices.map(w=>`<button class="choice-card" data-action="listen-choice" data-id="${w.id}"><span class="choice-emoji">${w.emoji}</span><strong>${escapeHtml(w.word)}</strong></button>`).join('')}</div><div class="feedback-message" id="gameFeedback">You can do it! 🌟</div><div class="game-actions"><button class="game-ghost" data-action="listen-hint">Need a hint?</button><button class="game-primary" id="listenNext" data-action="listen-next" disabled>${s.index===s.questions.length-1?'See results':'Next word →'}</button></div></div>`;}
function answerListen(id,button){const s=listenSession;if(!s||s.answered)return;const target=s.questions[s.index];s.answered=true;s.selected=id;workspace.querySelectorAll('[data-action="listen-choice"]').forEach(b=>{if(b.dataset.id===target.id)b.classList.add('correct');else if(b.dataset.id===id)b.classList.add('wrong');b.disabled=true;});const fb=el('gameFeedback');if(id===target.id){s.score+=10;s.correctCount++;fb.textContent=s.mode==='id-en'?`Great job! The English word is “${target.word}.” 🎉`:`Great job! The word is “${target.word}.” 🎉`;fb.classList.remove('wrong');setCharacterMessage('Amazing work! ✨');award({xp:10,coins:3,word:target,question:true,correct:true});confettiBurst();}else{fb.textContent=s.mode==='id-en'?`Good try! The English answer is “${target.word}.”`:`Good try! The correct word is “${target.word}.”`;fb.classList.add('wrong');setCharacterMessage('Keep trying! 💪');award({question:true,correct:false});}el('listenNext').disabled=false;el('listenNext').textContent=s.index===s.questions.length-1?'See results':'Next word →';}
function finishListenGame(){const s=listenSession;recordGameFinished();workspace.innerHTML=`<div class="result-panel"><div class="result-stars">${s.correctCount>=4?'🌟🌟🌟':s.correctCount>=2?'🌟🌟':'🌟'}</div><h3>${s.correctCount===5?'Word wizard!':s.correctCount>=3?'Great listening!':'Keep it up!'}</h3><p>You got ${s.correctCount} out of ${s.questions.length} answers right. Every practice makes you stronger.</p><div class="result-metrics"><div class="result-metric"><strong>${s.score}</strong><small>POINTS</small></div><div class="result-metric"><strong>+${s.correctCount*10}</strong><small>XP EARNED</small></div><div class="result-metric"><strong>+${s.correctCount*3}</strong><small>COINS</small></div></div><button class="game-primary" data-action="listen-replay">Play again →</button> <button class="outline-button" data-action="games-home">Choose another game</button></div>`;setCharacterMessage('You did it! 🎉');listenSession=null;}
function startScramble(){const pool=shuffle(allWords.filter(w=>w.word.length>=3&&w.word.length<=9));scrambleSession={questions:pool.slice(0,5),index:0,score:0,correctCount:0,usedHints:0,answer:[],checked:false};renderScrambleQuestion();setViewActive('games');}
function createLetterTiles(word){return shuffle([...word.toUpperCase()].map((letter,index)=>({letter,id:`${index}-${Math.random().toString(16).slice(2,6)}`})));}
function renderScrambleQuestion(){const s=scrambleSession;if(!s)return;if(s.index>=s.questions.length){finishScramble();return;}const w=s.questions[s.index];if(!s.tiles||s.tileQuestion!==w.id){s.tiles=createLetterTiles(w.word);s.tileQuestion=w.id;s.answer=[];s.checked=false;}const slots=Array.from({length:w.word.length},(_,i)=>{const tileIndex=s.answer[i];return tileIndex===undefined?`<button class="letter-tile empty-slot" data-action="scramble-remove" data-index="${i}" aria-label="Empty letter slot">_</button>`:`<button class="letter-tile" data-action="scramble-remove" data-index="${i}">${s.tiles[tileIndex].letter}</button>`}).join('');workspace.innerHTML=`<div class="panel-head"><div><h3>Word Scramble 🔤</h3><p>Tap the letters in the correct order to build the word.</p></div><button class="inline-link" data-action="games-home">All games</button></div><div class="game-board"><div class="game-topline"><span class="game-count">WORD ${s.index+1} / ${s.questions.length}</span><span class="game-score">⭐ ${s.score} points</span></div><div class="game-prompt"><span class="prompt-emoji">${w.emoji}</span><h4>${escapeHtml(w.meaning)}</h4><p>What is this in English?</p></div><div class="scramble-answer">${slots}</div><div class="letter-bank">${s.tiles.map((tile,i)=>`<button class="letter-tile ${s.answer.includes(i)?'used':''}" data-action="scramble-letter" data-index="${i}" ${s.answer.includes(i)?'disabled':''}>${tile.letter}</button>`).join('')}</div><div class="feedback-message ${s.checked?'':' '}" id="scrambleFeedback">${s.checked?`Correct! ${escapeHtml(w.word)} means ${escapeHtml(w.meaning)}. 🎉`:s.answer.length?`${s.answer.length} of ${w.word.length} letters selected.`:'Choose the letters to spell the word.'}</div><div class="game-actions"><button class="game-ghost" data-action="scramble-hint">💡 Hint</button><button class="outline-button" data-action="scramble-clear">Clear</button><button class="game-primary" data-action="scramble-check" ${s.answer.length===0?'disabled':''}>Check word ✓</button></div><div class="game-actions" style="margin-top:5px"><button class="game-ghost" data-action="speak" data-id="${w.id}">🔊 Hear the answer</button><button class="game-primary" data-action="scramble-next" ${s.checked?'':'disabled'}>${s.index===s.questions.length-1?'See results':'Next word →'}</button></div></div>`;}
function checkScramble(){const s=scrambleSession;if(!s||s.checked)return;const w=s.questions[s.index];const answer=s.answer.map(i=>s.tiles[i].letter).join('').toLowerCase();const fb=el('scrambleFeedback');if(answer===w.word.toLowerCase()){s.checked=true;s.score+=10;s.correctCount++;fb.textContent=`Correct! ${w.word} means ${w.meaning}. 🎉`;fb.classList.remove('wrong');award({xp:10,coins:3,word:w,question:true,correct:true});confettiBurst();setCharacterMessage('Perfect spelling!');renderScrambleQuestion();}else{fb.textContent='Almost! Check the letters and try again.';fb.classList.add('wrong');award({question:true,correct:false});const board=workspace.querySelector('.scramble-answer');board.style.animation='shake .35s';setTimeout(()=>board.style.animation='',400);}}
function finishScramble(){const s=scrambleSession;recordGameFinished();workspace.innerHTML=`<div class="result-panel"><div class="result-stars">🔤✨</div><h3>Spelling adventure complete!</h3><p>You solved ${s.correctCount} out of ${s.questions.length} words. Keep practicing to make spelling easier.</p><div class="result-metrics"><div class="result-metric"><strong>${s.score}</strong><small>POINTS</small></div><div class="result-metric"><strong>+${s.correctCount*10}</strong><small>XP EARNED</small></div></div><button class="game-primary" data-action="scramble-replay">Play again →</button> <button class="outline-button" data-action="games-home">Choose another game</button></div>`;scrambleSession=null;setCharacterMessage('Brilliant spelling! 🎉');}
function startMatching(){const pairs=shuffle(allWords).slice(0,4);matchSession={pairs,images:shuffle(pairs),words:shuffle(pairs),selected:null,matched:[],mistakes:0};renderMatching();setViewActive('games');}
function renderMatching(){const s=matchSession;if(!s)return;workspace.innerHTML=`<div class="panel-head"><div><h3>Picture Match 🧩</h3><p>Tap a picture, then tap the matching English word.</p></div><button class="inline-link" data-action="games-home">All games</button></div><div class="game-board"><div class="game-topline"><span class="game-count">MATCH THE PAIRS</span><span class="game-score">✅ ${Math.floor(s.matched.length/2)} / ${s.pairs.length}</span></div><div class="match-layout"><div class="match-column">${s.images.map(w=>`<button class="match-item ${s.matched.includes(w.id)?'matched':''} ${s.selected?.type==='image'&&s.selected.id===w.id?'selected':''}" data-action="match-select" data-type="image" data-id="${w.id}" ${s.matched.includes(w.id)?'disabled':''}><span class="match-emoji">${w.emoji}</span><span>Picture ${s.images.indexOf(w)+1}</span></button>`).join('')}</div><div class="match-column">${s.words.map(w=>`<button class="match-item ${s.matched.includes(w.id)?'matched':''} ${s.selected?.type==='word'&&s.selected.id===w.id?'selected':''}" data-action="match-select" data-type="word" data-id="${w.id}" ${s.matched.includes(w.id)?'disabled':''}>${escapeHtml(w.word)}</button>`).join('')}</div></div><div class="feedback-message" id="matchFeedback">${s.selected?'Now choose its matching word.':'Pick any picture to begin.'}</div><div class="game-actions"><button class="game-ghost" data-action="matching-restart">↻ Restart</button><button class="game-primary" data-action="matching-next" ${s.matched.length<s.pairs.length*2?'disabled':''}>${s.matched.length===s.pairs.length*2?'Next round →':'Match all pairs'}</button></div></div>`;if(s.matched.length===s.pairs.length*2){const fb=el('matchFeedback');if(fb)fb.textContent='Amazing! All pairs matched! 🎉';}}
function chooseMatch(type,id){const s=matchSession;if(!s||s.matched.includes(id))return;const fb=el('matchFeedback');if(!s.selected){s.selected={type,id};renderMatching();return;}if(s.selected.type===type){s.selected={type,id};renderMatching();return;}const otherId=s.selected.id;const imageId=type==='image'?id:otherId;const wordId=type==='word'?id:otherId;if(imageId===wordId){s.matched.push(id);s.matched.push(otherId);const w=wordById.get(id);award({xp:5,coins:2,word:w,question:true,correct:true});s.selected=null;if(s.matched.length===s.pairs.length*2){confettiBurst();setCharacterMessage('Perfect matching!');}renderMatching();}else{s.mistakes++;award({question:true,correct:false});s.selected=null;renderMatching();const msg=el('matchFeedback');if(msg){msg.textContent='Not quite! Try a different pair.';msg.classList.add('wrong');}const board=workspace.querySelector('.match-layout');if(board){board.style.animation='shake .35s';setTimeout(()=>board.style.animation='',400);}}}
function finishMatching(){const n=matchSession?.pairs.length||4;recordGameFinished();workspace.innerHTML=`<div class="result-panel"><div class="result-stars">🧩🌟</div><h3>All matched!</h3><p>You matched all ${n} pictures and words. You're building strong word connections.</p><div class="result-metrics"><div class="result-metric"><strong>${n}</strong><small>PAIRS</small></div><div class="result-metric"><strong>+${n*5}</strong><small>XP EARNED</small></div></div><button class="game-primary" data-action="matching-restart">Play again →</button> <button class="outline-button" data-action="games-home">Choose another game</button></div>`;matchSession=null;}
function showWordModal(word){if(!word)return;el('modalContent').innerHTML=`<div class="word-modal"><div class="word-modal-emoji">${word.emoji}</div><h2 id="modalTitle">${escapeHtml(word.word)}</h2><div class="meaning">${escapeHtml(word.meaning)}</div><div class="example"><strong>Example sentence</strong>${escapeHtml(word.example)}<br><span style="font-size:11px;opacity:.9">${escapeHtml(word.sentenceMeaning)}</span></div><div class="modal-actions"><button class="mint-button" data-action="modal-speak" data-id="${word.id}">🔊 Listen</button><button class="soft-button" data-action="modal-mark" data-id="${word.id}">✓ Mark as learned</button><button class="outline-button" data-action="modal-review" data-id="${word.id}">🔁 Review later</button></div></div>`;el('modalBackdrop').hidden=false;el('modalClose').focus();}
function closeModal(){el('modalBackdrop').hidden=true;}
function markKnown(word){if(!word)return;state.mastered=[...new Set([...state.mastered,word.id])];state.review=state.review.filter(id=>id!==word.id);award({xp:2,coins:1,word,correct:true});toast(`Nice! “${word.word}” added to your known words.`,'⭐');}
function markForReview(word){if(!word)return;state.review=[...new Set([...state.review,word.id])];saveState();toast(`“${word.word}” added to your review list.`,'🔁');}
function profileModal(){el('modalContent').innerHTML=`<div class="word-modal"><div class="word-modal-emoji">🧒</div><h2 id="modalTitle">Your learner profile</h2><div class="meaning">${escapeHtml(state.name)}</div><div class="example"><strong>${getLevel().name} · Level ${getLevel().number}</strong>${state.xp} XP · ${state.coins} coins · ${state.streak}-day streak</div><div class="profile-edit"><input id="modalNameInput" maxlength="24" value="${escapeHtml(state.name)}" placeholder="Your display name" aria-label="Your display name"><button class="mint-button" data-action="save-modal-name">Save</button></div><p style="font-size:11px;color:#a093ad">Your progress is saved on this browser and device.</p></div>`;el('modalBackdrop').hidden=false;}
function selectCategory(catId){const cat=categories.find(c=>c.id===catId);if(!cat)return;state.categoryVisits[catId]=(state.categoryVisits[catId]||0)+1;setView('vocabulary',false);renderVocabulary('',catId);workspace.scrollIntoView({behavior:'smooth',block:'start'});}
function wordOfDay(){const idx=(new Date().getFullYear()*366+new Date().getMonth()*31+new Date().getDate())%allWords.length;return allWords[idx];}
function useAction(action,btn){const id=btn.dataset.id;const word=id?wordById.get(id):null;switch(action){
 case 'open-category':selectCategory(btn.dataset.category);break;
 case 'all-vocabulary':selectedCategory='all';setView('vocabulary');break;
 case 'listen':case 'listen-english':openListenGame('en-en');break;
 case 'listen-indonesian':openListenGame('id-en');break;
 case 'streak-home':setView('streak');break;
 case 'streak-go-home':setView('home');break;
 case 'streak-practice':openListenGame(state.listenMode||'en-en');break;
 case 'flashcards':beginFlashcards();break;
 case 'scramble':startScramble();break;
 case 'matching':startMatching();break;
 case 'games-home':setView('games',false);break;
 case 'show-word':showWordModal(word);break;
 case 'speak':if(word)speak(word.word);break;
 case 'listen-target':if(listenSession){const target=listenSession.questions[listenSession.index];if(listenSession.mode==='id-en')speak(target.meaning,'id-ID');else speak(target.word,'en-US');}break;
 case 'listen-choice':answerListen(id,btn);break;
 case 'listen-next':if(listenSession?.answered){listenSession.index++;renderListenQuestion();}break;
 case 'listen-hint':if(listenSession){const target=listenSession.questions[listenSession.index];const fb=el('gameFeedback');fb.textContent=`Hint: the English answer starts with “${target.word[0].toUpperCase()}”.`;speak(target.word[0],'en-US');}break;
 case 'listen-replay':openListenGame();break;
 case 'scramble-letter':if(scrambleSession&&!scrambleSession.checked){const i=Number(btn.dataset.index);if(!scrambleSession.answer.includes(i)){scrambleSession.answer.push(i);renderScrambleQuestion();}}break;
 case 'scramble-remove':if(scrambleSession&&!scrambleSession.checked){scrambleSession.answer.splice(Number(btn.dataset.index),1);renderScrambleQuestion();}break;
 case 'scramble-clear':if(scrambleSession&&!scrambleSession.checked){scrambleSession.answer=[];renderScrambleQuestion();}break;
 case 'scramble-check':checkScramble();break;
 case 'scramble-hint':if(scrambleSession){const w=scrambleSession.questions[scrambleSession.index];const fb=el('scrambleFeedback');fb.textContent=`Hint: ${w.word.length} letters. It starts with “${w.word[0].toUpperCase()}”.`;speak(w.word[0]);scrambleSession.usedHints++;}break;
 case 'scramble-next':if(scrambleSession?.checked){scrambleSession.index++;scrambleSession.tiles=null;renderScrambleQuestion();}break;
 case 'scramble-replay':startScramble();break;
 case 'match-select':chooseMatch(btn.dataset.type,id);break;
 case 'matching-restart':startMatching();break;
 case 'matching-next':if(matchSession&&matchSession.matched.length===matchSession.pairs.length*2)finishMatching();break;
 case 'flash-prev':flashIndex=Math.max(0,flashIndex-1);flashFlipped=false;renderFlashcard();break;
 case 'flash-next':flashIndex++;if(flashIndex>=flashDeck.length){toast('Flashcard deck complete! Great focus.','🃏');flashIndex=0;flashFlipped=false;}else flashFlipped=false;renderFlashcard();break;
 case 'mark-known':if(word)markKnown(word);flashIndex=Math.min(flashIndex+1,flashDeck.length-1);flashFlipped=false;renderFlashcard();break;
 case 'mark-review':if(word)markForReview(word);flashIndex=Math.min(flashIndex+1,flashDeck.length-1);flashFlipped=false;renderFlashcard();break;
 case 'review-words':beginFlashcards(state.review.map(wid=>wordById.get(wid)).filter(Boolean));break;
 case 'save-name':{const input=el('nameInput');if(input&&input.value.trim()){state.name=input.value.trim();saveState();renderProgress();updateStatsUI();toast('Name saved!','👋');}break;}
 case 'save-modal-name':{const input=el('modalNameInput');if(input&&input.value.trim()){state.name=input.value.trim();saveState();updateStatsUI();closeModal();toast('Name saved!','👋');}break;}
 case 'modal-speak':if(word)speak(word.word);break;
 case 'modal-mark':if(word){markKnown(word);closeModal();}break;
 case 'modal-review':if(word){markForReview(word);closeModal();}break;
 default:break;
}}
workspace.addEventListener('click',event=>{const btn=event.target.closest('[data-action]');if(btn&&!btn.disabled){useAction(btn.dataset.action,btn);}});
workspace.addEventListener('input',event=>{if(event.target.id==='vocabSearch'){const category=categories.find(c=>c.id===selectedCategory);const list=selectedCategory==='all'?allWords:(category?.words||allWords);const text=event.target.value.toLowerCase().trim();const filtered=list.filter(w=>`${w.word} ${w.meaning} ${w.category}`.toLowerCase().includes(text));const listEl=el('wordList');if(listEl)listEl.innerHTML=renderWordRows(filtered);}});
workspace.addEventListener('change',event=>{if(event.target.id==='categoryFilter'){selectedCategory=event.target.value;renderVocabulary(el('vocabSearch')?.value||'',selectedCategory);}});
el('modalContent').addEventListener('click',event=>{const btn=event.target.closest('[data-action]');if(btn&&!btn.disabled){useAction(btn.dataset.action,btn);}});

document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>setView(btn.dataset.view)));
el('brandHome').addEventListener('click',()=>{window.scrollTo({top:0,behavior:'smooth'});setView('home',false);});
el('backToHome').addEventListener('click',()=>{setView('home',false);el('heroSection').scrollIntoView({behavior:'smooth',block:'start'});});
el('continueLearning').addEventListener('click',()=>openListenGame(state.listenMode||'en-en'));
el('scenePlay').addEventListener('click',()=>openListenGame(state.listenMode||'en-en'));
el('listenMatchShortcut').addEventListener('click',()=>openListenGame(state.listenMode||'en-en'));
el('sceneFlashcards').addEventListener('click',()=>beginFlashcards());
el('sceneListen').addEventListener('click',()=>{const w=wordById.get(state.lastWordId)||wordOfDay();speak(w.word);setCharacterMessage(`Listen: ${w.word}!`);});
document.querySelectorAll('.word-sticker').forEach(btn=>btn.addEventListener('click',()=>{const w=wordByName.get(btn.dataset.word);showWordModal(w);if(w)speak(w.word);}));
el('wordOfDayButton').addEventListener('click',()=>showWordModal(wordOfDay()));
el('profileButton').addEventListener('click',profileModal);
el('streakShortcut').addEventListener('click',()=>setView('streak'));
el('modalClose').addEventListener('click',closeModal);
el('modalBackdrop').addEventListener('click',event=>{if(event.target===el('modalBackdrop'))closeModal();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key===' '&&event.target===el('flashCard')){event.preventDefault();el('flashCard').click();}});
el('soundToggle').addEventListener('click',()=>{state.sound=!state.sound;el('soundToggle').textContent=state.sound?'🔊':'🔇';el('soundToggle').title=state.sound?'Sound on':'Sound off';saveState();if(!state.sound&&'speechSynthesis'in window)window.speechSynthesis.cancel();toast(state.sound?'Sound enabled':'Sound muted',state.sound?'🔊':'🔇');});
el('resetProgress').addEventListener('click',()=>{if(confirm('Reset all WordMaster Academy demo progress on this browser? This cannot be undone.')){state=defaultState();saveState();flashDeck=[];flashIndex=0;listenSession=null;scrambleSession=null;matchSession=null;setView('home',false);updateStatsUI();toast('Demo progress reset. Fresh start!','🌱');window.scrollTo({top:0,behavior:'smooth'});}});

// Count one daily login on app launch. Refreshing again on the same calendar day does not increase the streak.
startActiveDay();saveState();
// initial boot
el('soundToggle').textContent=state.sound?'🔊':'🔇';el('soundToggle').title=state.sound?'Sound on':'Sound off';
updateStatsUI();renderHome();
if('speechSynthesis'in window){window.speechSynthesis.getVoices();window.speechSynthesis.onvoiceschanged=()=>window.speechSynthesis.getVoices();}
